package kome.common.data;
import lotr.common.LOTRPlayerData;import lotr.common.entity.npc.LOTREntityNPC;import lotr.common.quest.LOTRMiniQuest;import net.minecraft.init.Items;import net.minecraft.item.ItemStack;import net.minecraft.nbt.NBTTagCompound;
/** Native presentation shell for the canonical Trial of Standing offer. */
public final class KOMELiegeOfferQuest extends LOTRMiniQuest {
    public boolean isLordshipOffer(){return "lordship_trial".equals(kind);}
    public static KOMELiegeOfferQuest createLordship(LOTRPlayerData d,LOTREntityNPC n,long day,KOMELordshipTrial t){KOMELiegeOfferQuest q=create(d,n,day,KOMELordshipTrialPresentation.speech(t,t.objective.stage==KOMEKnightCommission.Stage.OFFERED?"offer":"progress"),"lordship_trial");if(q!=null)q.commissionToken=t.objective.token;return q;}
    public static final String TYPE="KOMELiegeOffer";private String commissionToken=""; public boolean isCommissionOffer(){return "knight_commission".equals(kind);} public String commissionToken(){return commissionToken;}
    public static KOMELiegeOfferQuest createCommission(LOTRPlayerData d,LOTREntityNPC n,long day,KOMEKnightCommission a){KOMELiegeOfferQuest q=create(d,n,day,KOMEKnightCommissionPresentation.speech(a,a.stage==KOMEKnightCommission.Stage.OFFERED?"offer":"progress"),"knight_commission");if(q!=null)q.commissionToken=a.token;return q;}
    private static final String SPONSORSHIP="sponsorship",STANDING_TRIAL="standing_trial",REPLACEMENT="replacement_liege";private long window;private String story="",kind=SPONSORSHIP;
    public KOMELiegeOfferQuest(LOTRPlayerData d){super(d);}
    private KOMELiegeOfferQuest(LOTRPlayerData d,LOTREntityNPC n,long w,String s,String k,LOTRMiniQuest template){super(d);window=w;story=s==null?"":s;kind="lordship_trial".equals(k)?"lordship_trial":"knight_commission".equals(k)?"knight_commission":STANDING_TRIAL.equals(k)?STANDING_TRIAL:REPLACEMENT.equals(k)?REPLACEMENT:SPONSORSHIP;copyNativePresentation(template);setNPCInfo(n);quoteStart=story;}
    public static KOMELiegeOfferQuest createStandingTrial(LOTRPlayerData d,LOTREntityNPC n,long day){return create(d,n,day,"You have earned the right to be tested. If you would rise in standing, accept this Trial of Standing and prove yourself worthy of greater responsibility.",STANDING_TRIAL);}
    public static KOMELiegeOfferQuest createReplacement(LOTRPlayerData d,LOTREntityNPC n,long day){return create(d,n,day,"You have already earned your standing. If you seek a Liege, I will receive your service and offerings. No new Trial of Standing is required.",REPLACEMENT);}
    private static KOMELiegeOfferQuest create(LOTRPlayerData d,LOTREntityNPC n,long w,String s,String k){if(n==null||s==null||s.trim().length()==0)return null;LOTRMiniQuest template=n.createMiniQuest();if(!hasNativePresentation(template))return null;return new KOMELiegeOfferQuest(d,n,w,s,k,template);}
    private void copyNativePresentation(LOTRMiniQuest q){questGroup=q.questGroup;speechBankStart=q.speechBankStart;speechBankProgress=q.speechBankProgress;speechBankComplete=q.speechBankComplete;speechBankTooMany=q.speechBankTooMany;quoteComplete=q.quoteComplete;quotesStages.addAll(q.quotesStages);}
    private static boolean hasNativePresentation(LOTRMiniQuest q){return q!=null&&q.questGroup!=null&&nonEmpty(q.speechBankStart)&&nonEmpty(q.speechBankProgress)&&nonEmpty(q.speechBankComplete)&&nonEmpty(q.speechBankTooMany)&&nonEmpty(q.quoteStart)&&nonEmpty(q.quoteComplete);}private static boolean nonEmpty(String s){return s!=null&&s.length()!=0;}
    public boolean expired(long w){return window!=w;}public boolean isStandingTrialOffer(){return STANDING_TRIAL.equals(kind);}public boolean isReplacementOffer(){return REPLACEMENT.equals(kind);}
    public String getQuestObjective(){return isLordshipOffer()?"Trial of Lordship for "+entityNameFull:isCommissionOffer()?"Liege Commission for "+entityNameFull:isReplacementOffer()?"Establish a Liege relationship with "+entityNameFull:"Undertake a Trial of Standing for "+entityNameFull;}public String getObjectiveInSpeech(){return isLordshipOffer()?"answer for those entrusted to your charge":isCommissionOffer()?"fulfil this commission":isReplacementOffer()?"receive your service as Liege":"undertake this Trial of Standing";}public String getProgressedObjectiveInSpeech(){return getObjectiveInSpeech();}public String getQuestProgress(){return isLordshipOffer()?"Trial of Lordship":isCommissionOffer()?"Liege Commission":isReplacementOffer()?"Liege relationship":"Trial of Standing";}public String getQuestProgressShorthand(){return isLordshipOffer()?"Lordship Trial":isCommissionOffer()?"Commission":isReplacementOffer()?"Liege":"Standing Trial";}public float getCompletionFactor(){return 0;}public ItemStack getQuestIcon(){return new ItemStack(Items.iron_sword);}public float getAlignmentBonus(){return 0;}public int getCoinBonus(){return 0;}public boolean canPlayerAccept(net.minecraft.entity.player.EntityPlayer player){return isStandingTrialOffer()||isReplacementOffer()||isCommissionOffer()||isLordshipOffer();}
    public void writeToNBT(NBTTagCompound t){super.writeToNBT(t);t.setLong("KOMEWindow",window);t.setString("KOMEStory",story);t.setString("KOMEKind",kind);t.setString("KOMECommission",commissionToken);}public void readFromNBT(NBTTagCompound t){super.readFromNBT(t);window=t.getLong("KOMEWindow");story=t.getString("KOMEStory");kind=t.hasKey("KOMEKind")?t.getString("KOMEKind"):SPONSORSHIP;commissionToken=t.getString("KOMECommission");if(!STANDING_TRIAL.equals(kind)&&!REPLACEMENT.equals(kind)&&!isCommissionOffer()&&!isLordshipOffer())kind=SPONSORSHIP;quoteStart=story;}
}
